import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String tenantId = (String) req.getAttribute("X-Tenant-Id");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Template-based query construction for multi-tenant reporting
        Map<String, String> params = new HashMap<>();
        params.put("tenant", tenantId);
        params.put("range", dateRange);
        params.put("reportTable", getTableForReport(reportType));

        String baseQuery = "SELECT * FROM ${reportTable} WHERE tenant_id = '${tenant}' " +
                          "AND created_at > NOW() - INTERVAL '${range}'";

        if (sortCol != null && !sortCol.isEmpty()) {
            // Allowlist check for sort column
            if (!isValidSortColumn(sortCol)) {
                resp.sendError(400, "Invalid sort column");
                return;
            }
            baseQuery += " ORDER BY " + sortCol;
        }

        StringSubstitutor sub = new StringSubstitutor(params);
        String finalQuery = sub.replace(baseQuery);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(finalQuery)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print(resultSetToJson(rs));

        } catch (SQLException e) {
            resp.sendError(500, "Query execution failed");
        }
    }

    private String getTableForReport(String type) {
        switch (type) {
            case "sales": return "report_sales";
            case "inventory": return "report_inventory";
            case "users": return "report_users";
            default: return "report_general";
        }
    }

    private boolean isValidSortColumn(String col) {
        Set<String> allowed = new HashSet<>(Arrays.asList(
            "created_at", "amount", "name", "status", "id"
        ));
        return allowed.contains(col.toLowerCase().trim());
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        StringBuilder sb = new StringBuilder("[");
        boolean first = true;
        while (rs.next()) {
            if (!first) sb.append(",");
            sb.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) sb.append(",");
                sb.append("\"").append(meta.getColumnName(i)).append("\":");
                sb.append("\"").append(rs.getString(i)).append("\"");
            }
            sb.append("}");
            first = false;
        }
        sb.append("]");
        return sb.toString();
    }
}
